$ErrorActionPreference='Stop'
$b='C:\Users\nicho\backups\hermes-final-20261016'
if(@(Get-CimInstance Win32_Process|Where-Object {$_.CommandLine -match 'hermes-final-20261016\\archive-(pc|reconcile)\.py'}).Count){throw 'Archive controller still running; no reconciliation launch'}
if(Test-Path (Join-Path $b 'reconcile-20261016')){throw 'Reconciliation directory exists; inspect source before any retry'}
$v=Get-Content (Join-Path $b 'verification.json') -Raw|ConvertFrom-Json
if($v.state -ne 'needs_review' -or @($v.errors).Count -ne 3220){throw 'Unexpected verification state'}
$raw=[IO.File]::ReadAllBytes((Join-Path $b 'robocopy-local-hermes.log'))
$log=[Text.Encoding]::UTF8.GetString($raw)
if($log -notmatch 'supervisor\.lock' -or $log -notmatch 'ERROR\s+33'){throw 'Copy failure log does not match known lock gap'}
$dest=Join-Path $b 'archive-reconcile.py'
$bytes=[Convert]::FromBase64String('')
$f=[IO.File]::Open($dest,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read)
try{$f.Write($bytes,0,$bytes.Length)}finally{$f.Dispose()}
if((Get-FileHash $dest).Hash -ne 'DC06932A9396508C621BC57C71654160E7DA9FE781180C4049672E29E4F9EC1F'){throw 'Reconcile source hash mismatch'}
$r=Invoke-CimMethod -ClassName Win32_Process -MethodName Create -Arguments @{CommandLine=('C:\Python314\python.exe '+$dest);CurrentDirectory=$b}
if($r.ReturnValue -ne 0){throw 'Reconcile WMI launch failed; inspect source before retry'}
$proc=Get-CimInstance Win32_Process -Filter "ProcessId=$($r.ProcessId)"
[pscustomobject]@{at=(Get-Date -Format o);pid=$r.ProcessId;created=if($proc -and $proc.CreationDate){$proc.CreationDate.ToString('o')}else{$null};source=$dest;sha256='DC06932A9396508C621BC57C71654160E7DA9FE781180C4049672E29E4F9EC1F';original_controller_absent=$true;copy_log_known_lock_only=$true;status='started; not yet verified'}|ConvertTo-Json
